//! V3 increment 1 cases M1-M9 from the independent acceptance report.
use soliddraft_kernel_catallax::CatallaxKernel;
use soliddraft_model::{Command, Document, FileError, configs::Grid, display, values::Input};
use std::sync::Arc;

fn kernel() -> Arc<CatallaxKernel> {
    Arc::new(CatallaxKernel::new())
}
fn part() -> Document {
    // Generated by unmodified main 623a8fc with scenario steps 1-10.
    let mut doc = Document::from_part_json(include_str!("fixtures/configurations-base.json"), kernel()).unwrap();
    doc.rebuild();
    doc
}
fn set(d: &mut Document, name: &str, expression: &str) {
    d.execute(Command::SetValue { name: name.into(), expression: expression.into() }).unwrap();
}
fn add(d: &mut Document, name: &str) {
    d.execute(Command::AddConfiguration { name: name.into() }).unwrap();
}
fn override_value(d: &mut Document, configuration: &str, name: &str, expression: &str) {
    d.execute(Command::SetConfigurationValue {
        configuration: configuration.into(),
        name: name.into(),
        expression: expression.into(),
    })
    .unwrap();
}
fn activate(d: &mut Document, name: &str) {
    d.execute(Command::ActivateConfiguration { name: name.into() }).unwrap();
}
fn numbers(d: &Document, width: f64, depth: f64) {
    let v = d.values().summary();
    assert_eq!(v[0]["value"].as_f64().unwrap(), width);
    assert_eq!(v[1]["value"].as_f64().unwrap(), depth);
}
fn refused(d: &mut Document, command: Command, text: &str) {
    let before = (d.part_json(), d.semantic_hash(), d.geometry_hash(), d.undo_depth());
    let error = d.execute(command).unwrap_err().to_string();
    assert!(error.contains(text), "{error}");
    assert_eq!((d.part_json(), d.semantic_hash(), d.geometry_hash(), d.undo_depth()), before);
}

#[test]
fn m1_values_file_without_rows_keeps_hashes() {
    let bytes = include_bytes!("fixtures/bracket-named.dwprt");
    let expected: serde_json::Value = serde_json::from_str(include_str!("fixtures/bracket-named.info.json")).unwrap();
    let doc = Document::from_bytes(bytes, kernel()).unwrap();
    assert!(doc.truth().get("configurations").is_none());
    assert_eq!(doc.semantic_hash().to_string(), expected["revision"].as_str().unwrap());
    assert_eq!(doc.geometry_hash().to_string(), expected["geometry_hash"].as_str().unwrap());
    let reopened = Document::from_bytes(&doc.to_bytes().unwrap(), kernel()).unwrap();
    assert_eq!(doc.semantic_hash(), reopened.semantic_hash());
    assert_eq!(doc.geometry_hash(), reopened.geometry_hash());
}

#[test]
fn m2_variant_identity_and_saved_meshes() {
    let mut d = part();
    let original = d.geometry_hash();
    add(&mut d, "Narrow");
    assert_eq!(original, d.geometry_hash());
    override_value(&mut d, "Narrow", "plate_w", "120");
    add(&mut d, "Wide");
    override_value(&mut d, "Wide", "plate_w", "6 in");
    let default = (d.semantic_hash(), d.geometry_hash());
    let mut hashes = Vec::new();
    for (name, lo, hi) in [("Narrow", 0.0, 120.0), ("Wide", -16.2, 136.2)] {
        activate(&mut d, name);
        hashes.push((d.semantic_hash(), d.geometry_hash()));
        let bytes = d.to_bytes().unwrap();
        for level in display::SAVED {
            let (mesh, _) = display::read(&bytes, level).unwrap().expect("saved active mesh");
            let min = mesh.positions.iter().map(|p| p[0] as f64).fold(f64::INFINITY, f64::min);
            let max = mesh.positions.iter().map(|p| p[0] as f64).fold(f64::NEG_INFINITY, f64::max);
            assert!((min - lo).abs() < 1e-3, "{name} {level:?}: {min}");
            assert!((max - hi).abs() < 1e-3, "{name} {level:?}: {max}");
        }
    }
    assert_ne!(hashes[0].0, hashes[1].0);
    assert_ne!(hashes[0].1, hashes[1].1);
    assert!(hashes.iter().all(|h| h.0 != default.0 && h.1 != default.1));
    activate(&mut d, "Narrow");
    assert_eq!((d.semantic_hash(), d.geometry_hash()), hashes[0]);
    activate(&mut d, "Wide");
    assert_eq!((d.semantic_hash(), d.geometry_hash()), hashes[1]);
    activate(&mut d, "Default");
    assert_eq!((d.semantic_hash(), d.geometry_hash()), default);
}

#[test]
fn m3_sparse_rows_inherit_default_edits() {
    let mut d = part();
    add(&mut d, "Narrow");
    override_value(&mut d, "Narrow", "plate_w", "120");
    add(&mut d, "Tall");
    override_value(&mut d, "Tall", "flange_d", "80");
    activate(&mut d, "Narrow");
    numbers(&d, 120.0, 60.0);
    activate(&mut d, "Tall");
    numbers(&d, 140.0, 80.0);
    activate(&mut d, "Default");
    set(&mut d, "plate_w", "130");
    numbers(&d, 130.0, 65.0);
    activate(&mut d, "Narrow");
    numbers(&d, 120.0, 60.0);
    activate(&mut d, "Tall");
    numbers(&d, 130.0, 80.0);
}

#[test]
fn m4_set_value_writes_the_supplying_layer() {
    let mut d = part();
    add(&mut d, "Narrow");
    override_value(&mut d, "Narrow", "plate_w", "120");
    activate(&mut d, "Narrow");
    set(&mut d, "plate_w", "125");
    numbers(&d, 125.0, 62.5);
    activate(&mut d, "Default");
    numbers(&d, 140.0, 70.0);
    activate(&mut d, "Narrow");
    set(&mut d, "flange_d", "50");
    numbers(&d, 125.0, 50.0);
    activate(&mut d, "Default");
    numbers(&d, 140.0, 50.0);
}

#[test]
fn m5_rename_reaches_row_keys_and_expression_text() {
    let mut d = part();
    add(&mut d, "Narrow");
    override_value(&mut d, "Narrow", "plate_w", "120");
    add(&mut d, "Scaled");
    override_value(&mut d, "Scaled", "flange_d", "plate_w / 3");
    let hash = d.geometry_hash();
    d.execute(Command::RenameValue { name: "plate_w".into(), to: "bracket_w".into() }).unwrap();
    assert_eq!(d.geometry_hash(), hash);
    let rows = d.configuration_summary();
    assert_eq!(rows["rows"][1]["overrides"]["bracket_w"], "120");
    assert!(rows["rows"][1]["overrides"].get("plate_w").is_none());
    assert_eq!(rows["rows"][2]["overrides"]["flange_d"], "bracket_w / 3");
    activate(&mut d, "Narrow");
    numbers(&d, 120.0, 60.0);
}

#[test]
fn m6_default_edits_check_inactive_rows() {
    let mut d = Document::new("Rows", kernel());
    // Use one length driver without the bracket's width/depth coupling.
    let source = part();
    let feature = source.features()[0].clone();
    d.execute(Command::InsertFeature { feature: feature.clone(), position: 0 }).unwrap();
    set(&mut d, "a", "20");
    set(&mut d, "b", "10");
    let soliddraft_model::FeatureKind::Sketch(s) = &feature.kind else { panic!("sketch") };
    let constraint = s.sketch.constraints.iter().find(|c| c.value().is_some()).unwrap().id;
    d.execute(Command::Drive { input: Input::Dimension { feature: feature.id, constraint }, expression: "a".into() })
        .unwrap();
    add(&mut d, "R");
    override_value(&mut d, "R", "a", "b * 2");
    let before = d.part_json();
    let error = d.execute(Command::SetValue { name: "b".into(), expression: "a / 2".into() }).unwrap_err().to_string();
    assert!(error.contains("cycle") && error.contains('R'), "{error}");
    assert_eq!(d.part_json(), before);
    set(&mut d, "k", "5");
    add(&mut d, "S");
    override_value(&mut d, "S", "a", "k * 5");
    refused(&mut d, Command::SetValue { name: "k".into(), expression: "30 deg".into() }, "length");
}

#[test]
fn m7_invalid_rows_and_targets_leave_revision_unchanged() {
    let mut d = part();
    add(&mut d, "Narrow");
    for command in [
        Command::AddConfiguration { name: "Narrow".into() },
        Command::AddConfiguration { name: "Default".into() },
        Command::SetConfigurationValue {
            configuration: "missing".into(),
            name: "plate_w".into(),
            expression: "120".into(),
        },
        Command::SetConfigurationValue {
            configuration: "Narrow".into(),
            name: "missing".into(),
            expression: "120".into(),
        },
        Command::SetConfigurationValue {
            configuration: "Default".into(),
            name: "plate_w".into(),
            expression: "120".into(),
        },
        Command::ActivateConfiguration { name: "missing".into() },
    ] {
        refused(&mut d, command, "");
    }
}

#[test]
fn m8_row_edits_are_single_undo_entries() {
    let mut d = part();
    let before = (d.semantic_hash(), d.geometry_hash(), d.undo_depth());
    add(&mut d, "Narrow");
    override_value(&mut d, "Narrow", "plate_w", "120");
    let after = (d.semantic_hash(), d.geometry_hash(), d.undo_depth());
    assert_eq!(after.2, before.2 + 2);
    d.undo().unwrap();
    d.undo().unwrap();
    assert_eq!((d.semantic_hash(), d.geometry_hash(), d.undo_depth()), before);
    d.redo().unwrap();
    d.redo().unwrap();
    assert_eq!((d.semantic_hash(), d.geometry_hash(), d.undo_depth()), after);
}

#[test]
fn m9_damaged_configuration_truth_is_invalid() {
    let mut d = part();
    add(&mut d, "Narrow");
    override_value(&mut d, "Narrow", "plate_w", "120");
    for kind in 0..3 {
        let mut truth = d.truth();
        match kind {
            0 => truth["configurations"]["active"] = serde_json::json!("missing"),
            1 => truth["configurations"]["rows"][0]["overrides"]["missing"] = serde_json::json!("12"),
            _ => truth["configurations"]["rows"][0]["overrides"]["plate_w"] = serde_json::json!("flange_d * 2"),
        }
        assert!(matches!(Document::from_part_json(&truth.to_string(), kernel()), Err(FileError::Invalid(_))));
    }
}

fn narrow_for_feature_edit() -> Document {
    let mut doc = part();
    add(&mut doc, "Narrow");
    override_value(&mut doc, "Narrow", "plate_w", "120");
    activate(&mut doc, "Narrow");
    numbers(&doc, 120.0, 60.0);
    doc
}

fn flip_flange(doc: &Document) -> Command {
    let feature = &doc.features()[3];
    let mut kind = feature.kind.clone();
    let soliddraft_model::FeatureKind::Extrude(extrude) = &mut kind else { panic!("flange extrusion") };
    extrude.reverse = !extrude.reverse;
    Command::EditFeature { id: feature.id, kind }
}

#[test]
fn regression_feature_edit_undo_restores_configuration_truth() {
    let mut doc = narrow_for_feature_edit();
    let before = (doc.part_json(), doc.semantic_hash(), doc.geometry_hash(), doc.undo_depth());
    // The app wraps each ordinary feature edit in a batch.
    let edit = Command::Batch { label: "Flip flange".into(), commands: vec![flip_flange(&doc)] };
    doc.execute(edit).unwrap();
    let edited = (doc.part_json(), doc.semantic_hash(), doc.geometry_hash(), doc.undo_depth());
    assert_ne!(edited.0, before.0);
    doc.undo().unwrap();
    assert_eq!((doc.part_json(), doc.semantic_hash(), doc.geometry_hash(), doc.undo_depth()), before);
    doc.redo().unwrap();
    assert_eq!((doc.part_json(), doc.semantic_hash(), doc.geometry_hash(), doc.undo_depth()), edited);
}

#[test]
fn regression_failed_batch_restores_configuration_truth() {
    let mut doc = narrow_for_feature_edit();
    let before = (doc.part_json(), doc.semantic_hash(), doc.geometry_hash(), doc.undo_depth());
    let batch = Command::Batch {
        label: "Refused edit".into(),
        commands: vec![
            flip_flange(&doc),
            Command::RenameFeature { id: soliddraft_model::FeatureId(u32::MAX), name: "Missing".into() },
        ],
    };
    assert!(doc.execute(batch).is_err());
    assert_eq!((doc.part_json(), doc.semantic_hash(), doc.geometry_hash(), doc.undo_depth()), before);
}

// V3 increment 2: the whole table, text properties and old files.

const MAIN_PART: &[u8] = include_bytes!("fixtures/main-configured.dwprt");

fn configured() -> Document {
    Document::from_bytes(MAIN_PART, kernel()).unwrap()
}

fn with_cells(d: &Document, change: impl FnOnce(&mut Grid)) -> Grid {
    let mut grid = d.configuration_grid();
    change(&mut grid);
    grid
}

fn set_grid(d: &mut Document, grid: Grid) {
    d.execute(Command::SetConfigurationGrid { grid: Box::new(grid) }).unwrap();
}

#[test]
fn p_compat_a_main_file_keeps_its_identities_and_gains_nothing() {
    let expected: serde_json::Value = serde_json::from_str(include_str!("fixtures/main-configured.info.json")).unwrap();
    let doc = configured();
    assert_eq!(doc.id().to_string(), expected["id"].as_str().unwrap());
    assert_eq!(doc.semantic_hash().to_string(), expected["revision"].as_str().unwrap());
    assert_eq!(doc.geometry_hash().to_string(), expected["geometry_hash"].as_str().unwrap());
    assert!(doc.truth().get("properties").is_none());
    assert!(doc.part_json().find("\"properties\"").is_none(), "absent fields stay out of the file");
    let reopened = Document::from_bytes(&doc.to_bytes().unwrap(), kernel()).unwrap();
    assert_eq!(reopened.part_json(), doc.part_json());
    assert_eq!(reopened.semantic_hash(), doc.semantic_hash());
    assert_eq!(reopened.geometry_hash(), doc.geometry_hash());
}

#[test]
fn p_compat_default_only_properties_survive_and_bad_types_are_refused() {
    let mut doc = Document::new("Plain", kernel());
    let grid = with_cells(&doc, |g| {
        g.properties = vec!["title".into()];
        g.rows[0].properties.insert("title".into(), "Bracket, \"family\"".into());
    });
    let (hash, geometry) = (doc.semantic_hash(), doc.geometry_hash());
    set_grid(&mut doc, grid);
    assert_ne!(doc.semantic_hash(), hash);
    assert_eq!(doc.geometry_hash(), geometry, "text is not geometry");
    assert!(doc.configuration_grid().rows.len() == 1 && doc.truth().get("configurations").is_none());
    let back = Document::from_bytes(&doc.to_bytes().unwrap(), kernel()).unwrap();
    assert_eq!(back.resolved_properties()["title"], "Bracket, \"family\"");
    assert_eq!(back.semantic_hash(), doc.semantic_hash());

    let file = doc.truth();
    let mut wrong = file.clone();
    wrong["properties"] = serde_json::json!(5);
    let error = Document::from_part_json(&wrong.to_string(), kernel()).unwrap_err();
    assert!(matches!(error, FileError::Json(_)), "{error}");

    let mut d = configured();
    let grid = with_cells(&d, |g| {
        g.properties = vec!["title".into()];
        g.rows[1].properties.insert("title".into(), "Narrow title".into());
    });
    set_grid(&mut d, grid);
    let mut wrong = d.truth();
    wrong["configurations"]["rows"][0]["properties"]["title"] = serde_json::json!(5);
    let error = Document::from_part_json(&wrong.to_string(), kernel()).unwrap_err();
    assert!(matches!(error, FileError::Json(_)), "{error}");
    let mut wrong = d.truth();
    wrong["configurations"]["rows"][0]["properties"]["title"] = serde_json::json!("two\nlines");
    let error = Document::from_part_json(&wrong.to_string(), kernel()).unwrap_err();
    assert!(matches!(error, FileError::Invalid(_)), "{error}");
}

#[test]
fn the_table_is_one_step_with_sparse_rows_and_stable_ids() {
    let mut d = configured();
    let before = d.configuration_grid();
    let ids: Vec<_> = before.rows.iter().map(|r| r.id.clone()).collect();
    let (hash, geometry, depth) = (d.semantic_hash(), d.geometry_hash(), d.undo_depth());
    let grid = with_cells(&d, |g| {
        g.properties = vec!["title".into()];
        g.rows[0].properties.insert("title".into(), "Family".into());
        g.rows[1].values.insert("plate_w".into(), "6 in".into());
    });
    set_grid(&mut d, grid);
    d.rebuild();
    assert_eq!(d.undo_depth(), depth + 1);
    let after = d.configuration_grid();
    assert_eq!(after.rows[1].values["plate_w"], "152.4 mm", "unit literals keep V1's canonical form");
    assert!(!after.rows[1].values.contains_key("flange_d"), "a blank stays inherited");
    assert_eq!(after.rows.iter().map(|r| r.id.clone()).collect::<Vec<_>>(), ids);
    numbers(&d, 152.4, 76.2);
    assert_eq!(d.resolved_properties()["title"], "Family", "Narrow inherits the file's text");
    assert_ne!(d.geometry_hash(), geometry);
    d.undo().unwrap();
    assert_eq!((d.semantic_hash(), d.geometry_hash()), (hash.clone(), geometry.clone()));
    assert_eq!(d.configuration_grid(), before);
    assert!(d.resolved_properties().is_empty());
    d.redo().unwrap();
    assert_eq!(d.configuration_grid(), after);
    assert_eq!(d.resolved_properties()["title"], "Family");
}

#[test]
fn a_property_edit_rebuilds_nothing() {
    let mut d = configured();
    d.rebuild();
    let geometry = d.geometry_hash();
    let grid = with_cells(&d, |g| {
        g.rows[1].properties.insert("title".into(), "Own text".into());
    });
    let before = d.semantic_hash();
    set_grid(&mut d, grid);
    assert!(!d.is_dirty(), "text starts no rebuild");
    assert_ne!(d.semantic_hash(), before);
    assert_eq!(d.geometry_hash(), geometry);
    assert_eq!(d.resolved_properties()["title"], "Own text");
}

#[test]
fn a_candidate_is_refused_whole_and_names_its_cell() {
    let mut d = configured();
    let cases: Vec<(Grid, &str, Option<&str>, Option<&str>)> = vec![
        (
            with_cells(&d, |g| {
                g.rows[1].values.insert("plate_w".into(), "30 deg".into());
            }),
            "expected length (mm), found angle (deg)",
            Some("Narrow"),
            Some("plate_w"),
        ),
        (
            with_cells(&d, |g| {
                g.rows[1].values.insert("plate_w".into(), "flange_d * 2".into());
            }),
            "cycle",
            Some("Narrow"),
            Some("plate_w"),
        ),
        (
            with_cells(&d, |g| {
                g.rows[0].values.remove("hole_d");
            }),
            "missing required cell",
            Some("Default"),
            Some("hole_d"),
        ),
        (
            with_cells(&d, |g| {
                let extra = g.rows[1].clone();
                g.rows.push(extra);
            }),
            "duplicate configuration Narrow",
            None,
            None,
        ),
        (
            with_cells(&d, |g| {
                g.rows.pop();
            }),
            "missing configuration Narrow",
            None,
            None,
        ),
        (
            with_cells(&d, |g| {
                g.values[0].name = "missing_w".into();
            }),
            "unknown named value missing_w",
            None,
            None,
        ),
        (
            with_cells(&d, |g| {
                g.values[0].unit = "deg".into();
            }),
            "expected length (mm), found unit deg",
            None,
            Some("plate_w"),
        ),
    ];
    let truth = d.part_json();
    for (grid, reason, row, column) in cases {
        let refusal = d.check_configuration_grid(&grid).unwrap_err();
        assert!(refusal.reason.contains(reason), "{refusal}");
        assert_eq!((refusal.row.as_deref(), refusal.column.as_deref()), (row, column), "{refusal}");
        let error = d.execute(Command::SetConfigurationGrid { grid: Box::new(grid) }).unwrap_err().to_string();
        assert!(error.contains(reason), "{error}");
        assert_eq!(d.part_json(), truth);
    }
}
